import { describe, expect, test } from "bun:test";
import { plan } from "../src/cli";

describe("dependency planner", () => {
  test("plans branches deterministically and uses the lexicographically smallest critical path", () => {
    expect(
      plan({
        tasks: [
          { id: "ship", duration: 1, dependsOn: ["test", "build"] },
          { id: "test", duration: 2, dependsOn: ["lint"] },
          { id: "build", duration: 2, dependsOn: ["lint"] },
          { id: "lint", duration: 1 },
        ],
      }),
    ).toEqual({
      order: ["lint", "build", "test", "ship"],
      layers: [["lint"], ["build", "test"], ["ship"]],
      earliest: {
        build: { start: 1, finish: 3 },
        lint: { start: 0, finish: 1 },
        ship: { start: 3, finish: 4 },
        test: { start: 1, finish: 3 },
      },
      totalDuration: 4,
      criticalPath: ["lint", "build", "ship"],
    });
  });

  test("handles empty input, disconnected tasks, and zero-duration dependencies", () => {
    expect(plan({ tasks: [] })).toEqual({
      order: [],
      layers: [],
      earliest: {},
      totalDuration: 0,
      criticalPath: [],
    });

    const result = plan({
      tasks: [
        { id: "z", duration: 0, dependsOn: ["a"] },
        { id: "work", duration: 3 },
        { id: "a", duration: 0 },
      ],
    });
    expect(result.order).toEqual(["a", "work", "z"]);
    expect(result.layers).toEqual([["a", "work"], ["z"]]);
    expect(result.totalDuration).toBe(3);
    expect(result.criticalPath).toEqual(["work"]);
  });

  test("includes zero-duration nodes when they make an equal critical path lexicographically smaller", () => {
    expect(
      plan({
        tasks: [
          { id: "b", duration: 3, dependsOn: ["a"] },
          { id: "a", duration: 0 },
        ],
      }).criticalPath,
    ).toEqual(["a", "b"]);
  });

  test("rejects invalid task data", () => {
    expect(() => plan({ tasks: [{ id: "", duration: 1 }] })).toThrow("non-empty string");
    expect(() => plan({ tasks: [{ id: "a", duration: -1 }] })).toThrow("non-negative");
    expect(() =>
      plan({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] }),
    ).toThrow("unknown dependency");
    expect(() =>
      plan({ tasks: [{ id: "a", duration: 1, dependsOn: ["a"] }] }),
    ).toThrow("cannot depend on itself");
  });

  test("reports a deterministic concrete cycle", () => {
    expect(() =>
      plan({
        tasks: [
          { id: "c", duration: 1, dependsOn: ["b"] },
          { id: "b", duration: 1, dependsOn: ["c"] },
          { id: "a", duration: 1 },
        ],
      }),
    ).toThrow("dependency cycle: b -> c -> b");
  });

  test("supports ids that coincide with object prototype properties", () => {
    const result = plan({
      tasks: [
        { id: "constructor", duration: 1 },
        { id: "__proto__", duration: 2, dependsOn: ["constructor"] },
      ],
    });
    expect(result.earliest["__proto__"]).toEqual({ start: 1, finish: 3 });
    expect(JSON.parse(JSON.stringify(result)).earliest["__proto__"]).toEqual({
      start: 1,
      finish: 3,
    });
  });
});

export interface TaskInput {
  id: string;
  duration: number;
  dependsOn?: string[];
}

export interface Plan {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
}

